<?php $zawodnicy=[['nazwisko'=>'Anna Kowalska','okrazenia'=>[312,298,305]],['nazwisko'=>'Piotr Nowak','okrazenia'=>[355,430,341]],['nazwisko'=>'Marek Zieliński','okrazenia'=>[]],['nazwisko'=>'Ewa Wiśniewska','okrazenia'=>[402,377,395]]];$ile=0;$elita=0;$razem=0;$best=null;function czas($s){return floor($s/60).':'.str_pad($s%60,2,'0',STR_PAD_LEFT);} ?><!DOCTYPE html><html lang="pl"><head><meta charset="UTF-8"><title>Wyniki zawodów</title><style>body{font-family:Arial;background:#eee;margin:30px}h1{text-align:center}table{width:90%;margin:20px auto;border-collapse:collapse;background:#fff}th{background:#444;color:#fff}th,td{padding:10px;border:1px solid #ccc;text-align:left}.elita{background:#d9f2d9}.zaawansowany{background:#fff2bd}.amator{background:#ffd6d6}.brak{background:#d9ebff}tfoot td{background:#333;color:#fff;font-weight:bold}</style></head><body><h1>Wyniki zawodów</h1><table><tr><th>Zawodnik</th><th>Okrążenia</th><th>Najlepsze</th><th>Średnie</th><th>Kategoria</th><th>Uwagi</th></tr><?php foreach($zawodnicy as $z){$ile++;if(count($z['okrazenia'])==0){echo'<tr class="brak"><td>'.$z['nazwisko'].'</td><td colspan="5">brak ukończonych okrążeń</td></tr>';continue;}$a=$z['okrazenia'];$n=min($a);$razem+=count($a);if($best===null||$n<$best)$best=$n;if($n<300){$k='elita';$elita++;}elseif($n<360)$k='zaawansowany';else$k='amator';$u='';foreach($a as $x){if($x>=420){$u='słabe okrążenie';break;}}if($u==''){$r=true;foreach($a as $x){if($x>$n+15)$r=false;}if($r)$u='równe tempo';}$wyniki=[];foreach($a as $x)$wyniki[]=czas($x);echo'<tr class="'.$k.'"><td>'.$z['nazwisko'].'</td><td>'.implode(', ',$wyniki).'</td><td>'.czas($n).'</td><td>'.czas(round(array_sum($a)/count($a))).'</td><td>'.$k.'</td><td>'.$u.'</td></tr>';}?><tfoot><tr><td colspan="6">Zawodników: <?=$ile?> | Elita: <?=$elita?> | Najlepsze okrążenie: <?=czas($best)?> | Okrążeń łącznie: <?=$razem?></td></tr></tfoot></table></body></html>
